  "Food and drink by mouth for comfort, and mouth care, always continue. Tube feeding is a medical treatment and is a choice.": "آرام کے لیے منہ سے کھانا پینا اور منہ کی دیکھ بھال ہمیشہ جاری رہتے ہیں۔ نلی سے غذا دینا ایک طبی علاج ہے اور یہ آپ کی پسند ہے۔",
  "Food and drink by mouth, given by hand for comfort, as much as the person wants and can safely swallow.": "منہ سے کھانا اور پینا، آرام کے لیے ہاتھ سے دیا جائے، جتنا وہ شخص چاہے اور محفوظ طریقے سے نگل سکے۔",
  "for a patient who cannot decide, withholding or withdrawing life-sustaining treatment may need the Medical Board process (Common Cause 2023; Harish Rana 2026). This plan records wishes and clinical limits; it does not by itself legally authorise withholding treatment.": "جو مریض فیصلہ نہیں کر سکتے، ان کے لیے زندگی برقرار رکھنے والا علاج شروع نہ کرنے یا واپس لینے کے لیے میڈیکل بورڈ کا طریقہ کار ضروری ہو سکتا ہے (Common Cause 2023; Harish Rana 2026)۔ یہ پلان خواہشیں اور طبی حدیں درج کرتا ہے؛ یہ اپنے آپ علاج روکنے کی قانونی اجازت نہیں دیتا۔",
  "For each treatment, choose what you want in those situations. You can leave any as “Not decided”.": "ہر علاج کے لیے چنیں کہ ان حالات میں آپ کیا چاہتے ہیں۔ کسی کو بھی “طے نہیں” چھوڑ سکتے ہیں۔",
  "For example your municipal corporation or gram panchayat. Maharashtra and Karnataka (rural) have named custodians; Andhra Pradesh has not confirmed one yet. You can still sign and record “custodian pending”.": "جیسے آپ کی میونسپل کارپوریشن یا گرام پنچایت۔ مہاراشٹر اور کرناٹک (دیہی) نے کسٹوڈین طے کیے ہیں؛ آندھرا پردیش نے ابھی تصدیق نہیں کی ہے۔ آپ پھر بھی دستخط کر کے “کسٹوڈین باقی” درج کر سکتے ہیں۔",
  "For example, the palliative team’s day-and-night number.": "جیسے پیلیئیٹو ٹیم کا دن رات والا نمبر۔",
