  "If the family disagrees: hold one family meeting, go back to what the patient would want, and ask the ethics committee if still unresolved. Current treatment continues meanwhile.": "اگر گھر والے متفق نہ ہوں: ایک فیملی میٹنگ کریں، دیکھیں کہ مریض خود کیا چاہتے، اور پھر بھی حل نہ ہو تو ایتھکس کمیٹی سے پوچھیں۔ تب تک موجودہ علاج جاری رہے۔",
