  "It applies only when your doctors decide there is no reasonable chance you will recover, and more treatment would only make dying longer. Choose the situations:": "یہ تبھی لاگو ہوگی جب آپ کے ڈاکٹر طے کریں کہ آپ کے ٹھیک ہونے کا کوئی معقول امکان نہیں، اور مزید علاج صرف موت کے عمل کو لمبا کرے گا۔ حالات چنیں:",
  "It cannot ask for anything meant to end life. That is against the law.": "اس میں زندگی ختم کرنے کے لیے کوئی بھی چیز نہیں مانگی جا سکتی۔ یہ قانون کے خلاف ہے۔",
  "It is only about refusing treatments that would just prolong dying. Comfort care, pain relief and feeding by mouth always continue.": "یہ صرف ان علاجوں سے انکار کے بارے میں ہے جو بس موت کے عمل کو لمبا کرتے۔ آرام کی دیکھ بھال، درد سے راحت اور منہ سے کھلانا ہمیشہ جاری رہتے ہیں۔",
