  "Signs of dying (falling blood pressure, cold mottled hands and feet, jaw breathing, Cheyne–Stokes breathing, little urine) mean this plan needs urgent review. If the signs are unclear, get a second opinion — wrongly deciding someone is dying can make it come true.": "موت کے قریب ہونے کی نشانیاں (بلڈ پریشر گرنا، ہاتھ پیر ٹھنڈے اور دھبے دار، جبڑے سے سانس لینا، Cheyne–Stokes سانس، بہت کم پیشاب) کا مطلب ہے کہ اس پلان کا فوراً جائزہ چاہیے۔ اگر نشانیاں صاف نہ ہوں تو دوسری رائے لیں — کسی کو غلطی سے مرتا ہوا مان لینا اسے سچ کر سکتا ہے۔",
