  "TRANSFER-call-first": "ایمبولینس سے پہلے فون کرنے کے نمبر جوڑیں، تاکہ گھر والوں کو پتہ ہو کہ پہلے کسے فون کرنا ہے۔",
  "TRANSFER-reasons": "اسپتال جانے کی کم از کم ایک وجہ چنیں۔",
  "Transport": "آنے جانے کی مدد",
  "Transport home for last days with a nurse escort": "آخری دنوں کے لیے نرس کے ساتھ گھر لے جانا",
  "Transport with symptom relief only": "صرف علامات سے راحت کے ساتھ لے جانا",
  "Transport with symptom relief only (O₂ for breathlessness, pain relief, positioning; no CPR, no intubation)": "صرف علامات سے راحت کے ساتھ لے جانا (سانس پھولنے کے لیے O₂، درد سے راحت، صحیح طرح لٹانا؛ CPR نہیں، انٹیوبیشن نہیں)",
  "Travel": "سفر",
