  "Treatment calendar": "علاج کا کیلنڈر",
  "Treatment change": "علاج میں بدلاؤ",
  "Treatment choices are locked. First record that the illness has been explained as not curable and the family can say it back.": "علاج کے فیصلے بند ہیں۔ پہلے درج کریں کہ سمجھا دیا گیا ہے کہ یہ بیماری ٹھیک نہیں ہو سکتی، اور گھر والے اسے دہرا سکتے ہیں۔",
  "Treatment dates": "علاج کی تاریخیں",
  "Treatment event": "علاج کا واقعہ",
  "Treatment events": "علاج کے واقعات",
  "Treatment limits are filled in but the patient's values are blank. Write what matters to the patient, in their own words.": "علاج کی حدیں بھری ہیں مگر مریض کی اہم باتیں خالی ہیں۔ مریض کے لیے کیا اہم ہے، انہی کے الفاظ میں لکھیں۔",
  "Treatment name": "علاج کا نام",
  "Treatment steps stay locked until this is ticked.": "جب تک اس پر نشان نہ لگے، علاج والے مرحلے بند رہیں گے۔",
  "Treatment summary": "علاج کا خلاصہ",
  "Treatments": "علاج",
