  "Turn prescription photos into a medicine list": "نسخے کی فوٹو سے دواؤں کی فہرست بنائیں",
  "Turning and positioning for comfort.": "آرام کے لیے کروٹ بدلنا اور صحیح طرح لٹانا۔",
  "Turning in bed": "بستر پر کروٹ لینا",
  "Two original reports": "دو اصل رپورٹیں",
  "Two witnesses must then sign.": "پھر دو گواہوں کو دستخط کرنے ہوں گے۔",
  "Two witnesses will also need to sign.": "دو گواہوں کو بھی دستخط کرنے ہوں گے۔",
  "Type": "قسم",
  "Typed names; no verified digital signature.": "لکھے ہوئے نام؛ کوئی تصدیق شدہ ڈیجیٹل دستخط نہیں۔",
  "Typed signatures recorded in Sahara. Synthetic patient data for the healthathon. The SHA-256 of this file is shown in the app and kept in the audit log.": "سہارا میں درج لکھے ہوئے دستخط۔ ہیلتھاتھون کے لیے نقلی مریض کا ڈیٹا۔ اس فائل کا SHA-256 ایپ میں دکھایا گیا ہے اور آڈٹ لاگ میں رکھا گیا ہے۔",
