  "I saw the note read out and the person sign or give their thumb impression": "میں نے نوٹ پڑھ کر سنایا جاتا اور اس شخص کو دستخط کرتے یا انگوٹھے کا نشان لگاتے دیکھا",
  "ID type & number": "شناخت کی قسم اور نمبر",
  "If a non-governmental organisation has been taking care of the patients, contact details of their representative + declaration confirming consultation with the NGO": "اگر کوئی غیر سرکاری تنظیم مریضوں کی دیکھ بھال کر رہی ہو، تو اس کے نمائندے کی رابطہ تفصیلات + NGO سے مشاورت کی تصدیق کا اعلامیہ",
  "If not, what is the frequency of assessments, and the details of the person coordinating between the patient/family and the relevant hospital/centre": "اگر نہیں، تو جائزوں کی تعداد کتنی بار ہے، اور مریض/خاندان اور متعلقہ اسپتال/مرکز کے درمیان رابطہ کار شخص کی تفصیلات",
  "If withdrawal and withholding of treatment has been decided (as per Common Cause v Union of India, 2018 and 2023)": "اگر علاج واپس لینے اور روکنے کا فیصلہ ہو چکا ہو (Common Cause v Union of India، 2018 اور 2023 کے مطابق)",
  "Illness explained as not curable, and the family can say it back": "بیماری کو لاعلاج بتایا گیا ہے، اور خاندان اسے دہرا سکتا ہے",
  "Intubation and invasive mechanical ventilation": "انٹیوبیشن اور انویسیو مکینیکل وینٹی لیشن",
  "LEVEL": "سطح",
  "Language preferred": "پسندیدہ زبان",
  "Left out": "چھوڑ دیا گیا",
  "Lock this note version": "اس نوٹ ورژن کو لاک کریں",
  "Locked on ": "لاک کیا گیا بتاریخ ",
  "Locked until the illness is recorded as explained (Understanding step).": "جب تک بیماری کی وضاحت درج نہ ہو، لاک ہے (سمجھ کا مرحلہ)۔",
  "Locked until the surrogate’s promise is confirmed.": "جب تک متبادل فیصلہ ساز کے وعدے کی تصدیق نہ ہو، لاک ہے۔",
  "Loss of dignity in bathing, toileting or exposure": "نہانے، رفعِ حاجت یا جسم کھلنے میں عزتِ نفس کا مجروح ہونا",
  "Low-flow oxygen up to ____ L/min. Comfortable, no interference with talking, eating or being at home.": "____ L/min تک کم بہاؤ والی آکسیجن۔ آرام دہ، بولنے، کھانے یا گھر پر رہنے میں کوئی رکاوٹ نہیں۔",
  "Medical information and patient values": "طبی معلومات اور مریض کی اقدار",
  "Members present for discussion and relationship with the patient": "گفتگو میں موجود افراد اور مریض سے ان کا رشتہ",
  "NAME": "نام",
  "NGO consulted": "NGO سے مشاورت کی گئی",
  "NO — the patient is to be cared for where they are.": "نہیں — مریض کی دیکھ بھال وہیں کی جائے جہاں وہ ہے۔",
  "Name & relationship": "نام اور رشتہ",
  "Name in capitals": "نام بڑے حروف میں",
  "Name, relation, phone": "نام، رشتہ، فون",
  "Named by patient": "مریض کا نامزد کردہ",
  "Named in AMD": "AMD میں نامزد",
  "Nasal prongs / simple face mask": "ناک کی نلکیاں / سادہ چہرے کا ماسک",
  "Nasogastric (Ryle’s) tube": "ناک سے معدے کی (رائلز) ٹیوب",
  "No choices were stated in this conversation.": "اس گفتگو میں کوئی انتخاب بیان نہیں کیا گیا۔",
  "No directive and no recorded prior wishes. Decisions will be made in the patient’s best interests through family consensus with the team.": "کوئی ہدایت نہیں اور کوئی درج شدہ سابقہ خواہشات نہیں۔ فیصلے ٹیم کے ساتھ خاندان کے اتفاقِ رائے سے مریض کے بہترین مفاد میں کیے جائیں گے۔",
  "No words were heard. Choose the language, or type the conversation.": "کوئی الفاظ سنائی نہیں دیے۔ زبان منتخب کریں، یا گفتگو ٹائپ کریں۔",
  "Non-invasive ventilation (CPAP / BiPAP)": "نان انویسیو وینٹی لیشن (CPAP / BiPAP)",
  "Non-rebreather / venturi mask": "نان ری بریدر / وینچوری ماسک",
  "Not being able to recognise or respond to family": "خاندان کو پہچان نہ پانا یا ان کو جواب نہ دے پانا",
  "Note and sign": "نوٹ اور دستخط",
  "Note signed and locked": "نوٹ پر دستخط ہو گئے اور لاک کر دیا گیا",
  "Nurse involved in the discussion": "گفتگو میں شامل نرس",
  "ONLY FOR THE FOLLOWING (tick each that applies):": "صرف درج ذیل کے لیے (جو لاگو ہو ہر ایک پر نشان لگائیں):",
  "Only after discussion with the palliative care team": "صرف پیلی ایٹو کیئر ٹیم سے بات کرنے کے بعد",
  "Only if the renal failure is judged reversible": "صرف اگر گردوں کی ناکامی کو قابلِ واپسی سمجھا جائے",
  "Opening the sign-off…": "دستخط کا حصہ کھولا جا رہا ہے…",
  "Opens when the understanding above is confirmed.": "اوپر دی گئی سمجھ کی تصدیق ہونے پر کھلے گا۔",
  "Opioid and anxiolytic for breathlessness, fan, positioning, suction, mouth care. Oxygen used only if it makes the patient feel better — no saturation target is chased.": "سانس کی تنگی کے لیے اوپیئڈ اور بے چینی کم کرنے والی دوا، پنکھا، جسم کی پوزیشن، سکشن، منہ کی دیکھ بھال۔ آکسیجن صرف اس صورت میں جب اس سے مریض بہتر محسوس کرے — سیچوریشن کے کسی ہدف کے پیچھے نہیں جایا جاتا۔",
  "Other parameters": "دیگر پیمانے",
  "Other:": "دیگر:",
  "Others": "دیگر",
  "PRIMARY": "بنیادی",
  "Pain that cannot be controlled at home": "درد جو گھر پر قابو میں نہ آ سکے",
  "Palliative care physician name and hospital – and contact": "پیلی ایٹو کیئر معالج کا نام اور اسپتال – اور رابطہ",
  "Patient details": "مریض کی تفصیلات",
  "Patient’s capacity": "مریض کی فیصلہ کرنے کی اہلیت",
